-- Athena / Glue external table for the curated Divvy trip fact table.
-- Generated by scripts/04_data_dictionary.py - do not hand-edit.
-- After creating the table you MUST load the Hive partitions:
--     MSCK REPAIR TABLE divvy.trips_clean;

CREATE EXTERNAL TABLE IF NOT EXISTS divvy.trips_clean (
  `ride_id` string,
  `rideable_type` string,
  `member_casual` string,
  `started_at` timestamp,
  `ended_at` timestamp,
  `start_station_name` string,
  `start_station_id` string,
  `start_station_key` string,
  `end_station_name` string,
  `end_station_id` string,
  `end_station_key` string,
  `start_lat` double,
  `start_lng` double,
  `end_lat` double,
  `end_lng` double,
  `start_geohash7` string,
  `end_geohash7` string,
  `duration_min` float,
  `haversine_km` float,
  `avg_speed_kmh` float,
  `trip_type` string,
  `is_round_trip` boolean,
  `trip_date` string,
  `day` tinyint,
  `hour` tinyint,
  `day_of_week` tinyint,
  `day_name` string,
  `is_weekend` boolean,
  `season` string,
  `time_of_day` string,
  `is_rush_hour` boolean
)
PARTITIONED BY (
  `year`  smallint,
  `month` tinyint
)
STORED AS PARQUET
LOCATION 's3://<your-bucket>/curated/divvy_trips/'
TBLPROPERTIES ('parquet.compression'='SNAPPY');
